  `show_full_form` int(1) NOT NULL DEFAULT 0,
  `show_form_tour` int(1) NOT NULL DEFAULT 0,
  `form_tour` varchar(140) DEFAULT NULL,
  `is_single` int(1) NOT NULL DEFAULT 0,
